INSERT INTO TBL_FILE ( /* org.bplte.core.api.domain.file.mapper.FileMapper.insertFileList */
      ORIGINAL_NAME
    , STORED_NAME
    , STORED_PATH
    , EXTENSION
    , REF_TYPE
    , REF_ID
    , SORT_ORDER
    , ROLE_TYPE
    , DEL_YN
    , REG_DT
    , RGTR_ID
    , MDFCN_DT
    , MDFR_ID
) VALUES

    (
          #{item.originalName}
        , #{item.storedName}
        , #{item.storedPath}
        , #{item.extension}
        , #{item.refType.code}
        , #{item.refId}
        , #{item.sortOrder}
        , #{item.roleType.code}
        , 'N'
        , NOW()
        , #{item.rgtrId}
        , NOW()
        , #{item.mdfrId}
    )
